        throw new InputError(`${label}.dependsOn[${dependencyIndex}] must be a string`);
      }
      if (seenDependencies.has(dependency)) {
        throw new InputError(
          `${label}.dependsOn contains duplicate id: ${JSON.stringify(dependency)}`,
        );
