      (dependency) => earliest[dependency].finish === start,
    );
    if (criticalDependencies.length === 0) {
      criticalPathById.set(id, [id]);
    } else {
      let bestPrefix = criticalPathById.get(criticalDependencies[0]) as string[];
      for (const dependency of criticalDependencies.slice(1)) {
        const candidate = criticalPathById.get(dependency) as string[];
        if (compareSequences(candidate, bestPrefix) < 0) bestPrefix = candidate;
      }
      criticalPathById.set(id, [...bestPrefix, id]);
    }
